#extension GL_OES_standard_derivatives : enable
precision highp float;

uniform sampler2D u_video;
uniform sampler2D u_map;
uniform sampler2D u_blurred;
uniform float u_baseScale[3];
uniform float u_ratioX[3];
uniform float u_ratioY[3];
uniform float u_chromaAmount;
uniform float u_specStrength;
uniform float u_adaptStrength;
uniform float u_specLumaLow;
uniform float u_specLumaHigh;
uniform float u_hasBlur;
uniform vec4 u_bbox; // (x, y, w, h) normalised, y=0 at top
uniform vec3 u_circles[3]; // (cx, cy, radius) in bbox pixel space
uniform float u_scale[3]; // per-circle geometric press scale (1 = unscaled)
uniform vec4 u_bar; // (cx, cy, w, h) in bbox pixel space; w<=0 means inactive
uniform float u_barRadius; // corner radius for the rounded-rect bar lens
uniform float u_barBaseScale;
uniform float u_barRatioX;
uniform float u_barRatioY;
uniform vec2 u_bboxSize; // bbox (width, height) in pixels

varying vec2 v_uv;

void main() {
  vec2 uv = v_uv;
  vec2 bMin = u_bbox.xy;
  vec2 bSize = u_bbox.zw;
  vec2 bMax = bMin + bSize;

  // Outside bounding box → pass-through video
  if (uv.x < bMin.x || uv.x > bMax.x || uv.y < bMin.y || uv.y > bMax.y) {
    gl_FragColor = texture2D(u_video, uv);
    return;
  }

  // Map fragment UV → displacement texture UV
  vec2 mUV = (uv - bMin) / bSize;

  // Analytical SDF mask (pixel-perfect at any resolution). Tracks the
  // dominant region so per-region scale/ratio can be picked up via the
  // loop-constant index (safe in WebGL 1). After the circle loop we test the
  // rounded-rect "bar" region (when active) and take whichever has the
  // larger mask value. domCenter/domScale track the dominant lens so the
  // displacement map is sampled in its (press-)scaled space below.
  vec2 pxPos = mUV * u_bboxSize;
  float mask = 0.0;
  float baseScale = 0.0;
  float ratioX = 0.0;
  float ratioY = 0.0;
  // Map-sample scale assignment, tracked SEPARATELY from the tight SDF mask: a
  // pixel adopts a circle's press scale across the union of its original and
  // scaled radius (R * max(1, s)). That way the annulus a shrunk lens vacates
  // samples empty space instead of leaving the original rim stuck behind.
  // domScale = 1 (bar + background) → identity sample.
  vec2 domCenter = pxPos;
  float domScale = 1.0;
  float domDist = 1.0; // nearest normalised assignment distance (<1 = inside)
  for (int i = 0; i < 3; i++) {
    if (u_circles[i].z < 0.1) continue; // skip inactive circles
    float s = max(u_scale[i], 0.001);
    float R = u_circles[i].z;
    float rho = length(pxPos - u_circles[i].xy);
    // Visible lens SDF at the scaled radius → blur / specular gating.
    float dist = rho - R * s;
    float aa = fwidth(dist);
    float m = 1.0 - smoothstep(-aa, aa, dist);
    if (m > mask) {
      mask = m;
      baseScale = u_baseScale[i];
      ratioX = u_ratioX[i];
      ratioY = u_ratioY[i];
    }
    // Scale assignment over max(original, scaled) radius, PLUS a small FIXED
    // pixel margin so the region boundary clears the map's hard content edge at
    // r = R. A *fractional* margin scales with R, so a big lens (play) would
    // swallow its neighbours' regions and drag their rings in. 4px clears the
    // edge's AA band without ever reaching the gap to the next control.
    float nd = rho / (R * max(1.0, s) + 4.0);
    if (nd < domDist) {
      domDist = nd;
      domCenter = u_circles[i].xy;
      domScale = s;
    }
  }
  // Bar (rounded-rect) SDF — only when u_bar.zw > 0. The bar never scales, so
  // it keeps the identity map sample (domScale stays 1 for bar + background).
  if (u_bar.z > 0.1 && u_bar.w > 0.1) {
    vec2 q = abs(pxPos - u_bar.xy) - u_bar.zw * 0.5 + vec2(u_barRadius);
    float barDist =
      length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - u_barRadius;
    float aaBar = fwidth(barDist);
    float mBar = 1.0 - smoothstep(-aaBar, aaBar, barDist);
    if (mBar > mask) {
      mask = mBar;
      baseScale = u_barBaseScale;
      ratioX = u_barRatioX;
      ratioY = u_barRatioY;
    }
  }

  // Sample the displacement map at the dominant lens's scaled coordinate, so a
  // per-lens press scale shrinks the baked pattern around its center in
  // lockstep with the SDF radius above. domScale = 1 → identity (unscaled).
  vec2 scaledPx = domCenter + (pxPos - domCenter) / domScale;
  vec4 d = texture2D(u_map, scaledPx / u_bboxSize);

  // ── mapMatrix (feColorMatrix equivalent) ──
  float sr = d.r * ratioX + 0.5 * (1.0 - ratioX);
  float sg = d.g * ratioY + 0.5 * (1.0 - ratioY);

  // Displacement offset in full-video UV space
  vec2 off = vec2(sr - 0.5, sg - 0.5) * baseScale;

  // Choose source: blurred or raw video
  // Inside lens → blurred (if blur active), outside lens → raw
  // Blend by mask so the transition at edges is clean
  vec4 color;
  if (u_chromaAmount > 0.001) {
    float sR = 1.0 + u_chromaAmount * 0.2;
    float sG = 1.0 + u_chromaAmount * 0.1;
    if (u_hasBlur > 0.5) {
      color.r = mix(
        texture2D(u_video, clamp(uv + off * sR, 0.0, 1.0)).r,
        texture2D(u_blurred, clamp(uv + off * sR, 0.0, 1.0)).r,
        mask
      );
      color.g = mix(
        texture2D(u_video, clamp(uv + off * sG, 0.0, 1.0)).g,
        texture2D(u_blurred, clamp(uv + off * sG, 0.0, 1.0)).g,
        mask
      );
      color.b = mix(
        texture2D(u_video, clamp(uv + off, 0.0, 1.0)).b,
        texture2D(u_blurred, clamp(uv + off, 0.0, 1.0)).b,
        mask
      );
    } else {
      color.r = texture2D(u_video, clamp(uv + off * sR, 0.0, 1.0)).r;
      color.g = texture2D(u_video, clamp(uv + off * sG, 0.0, 1.0)).g;
      color.b = texture2D(u_video, clamp(uv + off,       0.0, 1.0)).b;
    }
    color.a = 1.0;
  } else {
    vec2 duv = clamp(uv + off, 0.0, 1.0);
    if (u_hasBlur > 0.5) {
      color = mix(texture2D(u_video, duv), texture2D(u_blurred, duv), mask);
    } else {
      color = texture2D(u_video, duv);
    }
  }

  // ── Adaptive specular + brightness (Apple-style vibrancy) ──
  // Compute perceptual luminance of the displaced video sample
  float luma = dot(color.rgb, vec3(0.299, 0.587, 0.114));

  // Specular: blend between additive (dark bg) and multiplicative (bright bg)
  float spec = d.b - 0.502;
  float lumaLo = min(u_specLumaLow, u_specLumaHigh);
  float lumaHi = max(u_specLumaLow, u_specLumaHigh);
  float darkBlend = smoothstep(lumaLo, lumaHi, luma);
  vec3 specAdd = color.rgb + spec * u_specStrength;
  vec3 specMul = color.rgb * (1.0 - spec * u_specStrength);
  color.rgb = mix(specAdd, specMul, darkBlend);
  color.rgb = max(color.rgb, vec3(0.0));

  // Brightness: pull toward mid-gray — darkens bright areas, brightens dark
  float correction = (0.5 - luma) * u_adaptStrength * mask;
  color.rgb += correction;

  gl_FragColor = color;
}

